const api = game.modules.get("elinvale-tools")?.api;
if (!api?.toggleTimeStop) {
  ui.notifications.warn("Elinvale tools: модуль не загружен или устарел — нет api.toggleTimeStop.");
  return;
}
// Работает на сцене, открытой у тебя сейчас (canvas.scene), не на активной.
await api.toggleTimeStop(canvas.scene);
